entries[84409] = { ["name"] = "Instabiles Zephyriumsprengpaket", ["text"] = "Wirken in 2 sek.\nTools: Gyromatischer Mikroregler\nReagenzien:\nEine Handvoll Obsidiumbolzen , Elektrifizierter Äther (2)\nBerufsausbilder:\nIngenieurskunst des Kataklysmus (5)\nKosten:\n15\n\nBenutzen: Sprengt verschlossene Türen und Kisten auf, die eine Fertigkeit von bis zu 35 im Schlossknacken benötigen\nBenötigt Ingenieurskunst des Kataklysmus\n(1)" }
