entries[84411] = { ["name"] = "Hochleistungsbolzenschusspistole", ["text"] = "Wirken in 3 sek.\nTools: Schmiedehammer , Gyromatischer Mikroregler\nReagenzien:\nObsidiumbarren (10), Eine Handvoll Obsidiumbolzen (8), Elektrifizierter Äther (4)\nBerufsausbilder:\nIngenieurskunst des Kataklysmus (15)\nKosten:\n50\n\nHochleistungsbolzenschusspistole\nWird bei Benutzung gebunden\nBenutzen: Feuert einige geladene Bolzen auf einen Feind ab und verursacht so 108 Schaden, ebenso wird ein gewirkter Zauber kurzzeitig unterbrochen. Verbraucht mit jedem Schuss eine Handvoll Obsidiumbolzen. (2 Min Abklingzeit)\n29\nBenötigt Ingenieurskunst des Kataklysmus\n(1)\n\"Fast so schwer zu bedienen wie herzustellen.\"" }
entries[84412] = { ["name"] = "Persönlicher Weltenzerstörer", ["text"] = "Wirken in 3.5 sek.\nTools: Hochleistungsbolzenschusspistole , Schmiedehammer\nReagenzien:\nObsidiumbarren (10), Eine Handvoll Obsidiumbolzen (8), Elektrifizierter Äther (8)\nBerufsausbilder:\nIngenieurskunst des Kataklysmus (25)\nKosten:\n1\n\nPersönlicher Weltenzerstörer\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren persönlichen Weltenzerstörer beschwören oder wieder freigeben.\n1 - 80 ( 80)" }
entries[84413] = { ["name"] = "Entwaffneter mechanischer Begleiter", ["text"] = "Wirken in 3.5 sek.\nTools: Hochleistungsbolzenschusspistole , Bogenlichtschraubenschlüssel\nReagenzien:\nObsidiumbarren (12), Eine Handvoll Obsidiumbolzen (4), Elektrifizierter Äther (8), Jaspis (2)\nBerufsausbilder:\nIngenieurskunst des Kataklysmus (25)\nKosten:\n1\n\nEntwaffneter mechanischer Begleiter\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren entwaffneten mechanischen Begleiter beschwören oder wieder freigeben.\n1 - 80 ( 80)" }
entries[84415] = { ["name"] = "Ködermeister Spinnerkasten", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer , Hochleistungsbolzenschusspistole\nReagenzien:\nElementiumbarren (20), Eine Handvoll Obsidiumbolzen (4)\nBerufsausbilder:\nIngenieurskunst des Kataklysmus (25)\nKosten:\n1\n\nKödermeister Spinnerkasten\nWird beim Anlegen gebunden\n36 Platz Angelkiste" }
entries[84416] = { ["name"] = "Elementiumwerkzeugkasten", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nElementiumbarren (15), Flüchtige Erde (12)\nBerufsausbilder:\nIngenieurskunst des Kataklysmus (25)\nKosten:\n1\n\nElementiumwerkzeugkasten\nWird beim Anlegen gebunden\n36 Platz Ingenieurstasche\n\"Möglicherweise der schönste Werkzeugkasten, der jemals erschaffen wurde, mit goldenen Intarsien.\"" }
entries[84417] = { ["name"] = "Unberechenbarer Donnerstock", ["text"] = "Wirken in 3 sek.\nTools: Schmiedehammer , Gyromatischer Mikroregler\nReagenzien:\nElektrifizierter Äther (2), Gehärteter Elementiumbarren (5), Flüchtiges Feuer (6)\nOptionale Reagenzien:\n[] (#47)\nBerufsausbilder:\nIngenieurskunst des Kataklysmus (45)\nKosten:\n1\n75\n\nUnberechenbarer Donnerstock\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n6 - 12 Schaden Geschwindigkeit 3.00\n(3.0 Schaden pro Sekunde)\n+4 Beweglichkeit\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 80 / 80\n31" }
entries[84418] = { ["name"] = "Elementiumdrachling", ["text"] = "Wirken in 3 sek.\nTools: Schmiedehammer , Hochleistungsbolzenschusspistole\nReagenzien:\nEine Handvoll Obsidiumbolzen (2), Elektrifizierter Äther (8), Elementiumbarren (16), Glutseidenstoff (20)\nOptionale Reagenzien:\n[] (#47)\nBerufsausbilder:\nIngenieurskunst des Kataklysmus (25)\nKosten:\n1\n\nElementiumdrachling\nWird beim Anlegen gebunden\nEinzigartig anlegbarSchmuck\nErhöht Eure Meisterschaftswertung um + 6.\nBenutzen: Aktiviert Euren Elementiumdrachling, der 1 Min. lang für Euch kämpft. (5 Min Abklingzeit)\n30\nBenötigt Ingenieurskunst des Kataklysmus\n(25)" }
entries[84419] = { ["name"] = "Herausforderungsruf", ["text"] = "Sofort 10 sek. Abklingzeit\nVerspottet das Ziel, damit es Euch angreift, hat aber keinerlei Effekt, wenn das Ziel Euch bereits angreift." }
