entries[84421] = { ["name"] = "Plünderang", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGehärteter Elementiumbarren (5), Elektrifizierter Äther (5)\nBerufsausbilder:\nIngenieurskunst des Kataklysmus (40)\nKosten:\n1\n50\n\nPlünderang\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Sammelt die Beute von einer Leiche in der Nähe ein. (3 Sek. Abklingzeit)\nBenötigt Ingenieurskunst des Kataklysmus\n(70)" }
entries[84424] = { ["name"] = "Unsichtbarkeitsfeld", ["text"] = "Wirken in 2 sek.\nBenötigt Gürtel\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nBausatz des Tüftlers\nBringt dauerhaft Tausende kleiner Spiegel an Eurem Gürtel an. Damit könnt Ihr versuchen, Euch außerhalb des Kampfes unsichtbar zu machen. (3 Min. Abklingzeit)\nBeruf:\nIngenieurskunst des Kataklysmus (1)\nEntdeckung:\nIngenieurskunstrezepte des Kataklysmus" }
entries[84425] = { ["name"] = "Pappkamerad", ["text"] = "Wirken in 2 sek.\nBenötigt Gürtel\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nBausatz des Tüftlers\nBringt dauerhaft ein winziges Gerät an Eurem Gürtel an. Damit könnt Ihr einen Pappkameraden erstellen, der von den Gegnern angegriffen wird. (5 Min. Abklingzeit)\nBeruf:\nIngenieurskunst des Kataklysmus (1)\nEntdeckung:\nIngenieurskunstrezepte des Kataklysmus" }
