entries[84429] = { ["name"] = "Goblinbarbecue", ["text"] = "Wirken in 2 sek.\nTools: Hochleistungsbolzenschusspistole , Bogenlichtschraubenschlüssel\nReagenzien:\nElementiumbarren (2), Zähes Fleisch (2), Lavaschuppenfilet (2)\nBerufsausbilder:\nIngenieurskunst des Kataklysmus (55)\nKosten:\n2\n25\n\nBenutzen: Richtet für Eure Gruppe oder Euren Schlachtzug ein Goblinbarbecuefestmahl her! Stellt im Verlauf von 30 Sek. 6510 Gesundheit und ( 1118 / 5 * 30) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 9 Ausdauer und ein für Euch nützlicher Wert wird um 9 erhöht.\n30\nBenötigt Kochkunst des Kataklysmus\n(25)" }
entries[84430] = { ["name"] = "Hitzebehandelter Spinnerbait", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nEine Handvoll Obsidiumbolzen , Elementiumbarren (4), Flüchtiges Feuer\nBerufsausbilder:\nIngenieurskunst des Kataklysmus (60)\nKosten:\n2\n50\n\n(2)\nBenutzen: Bei Anwendung auf Eure Angelrute wird Eure Angelfertigkeit 15 Min. lang um 10 erhöht.\nBenötigt Angeln des Kataklysmus\n(1)\n\"Funktioniert sogar in Lava!\"" }
