entries[84816] = { ["name"] = "Donnerknall", ["text"] = "Sofort\nFügt Gegnern in der Nähe 96 Naturschaden zu, erhöht die Zeit zwischen ihren Angriffen um 100% und verringert ihre Bewegungsgeschwindigkeit um 60%. Hält 8 Sek. lang an." }
entries[84817] = { ["name"] = "Zerschmetternder Wurf", ["text"] = "30 Meter Reichweite\nWirken in 1.5 sek. 5 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nWirft Eure Waffe nach dem Feind. Verursacht Waffenschaden verringert die Rüstung des Ziels 10 Sek. lang um 20%." }
