entries[84829] = { ["name"] = "Kettenblitzschlag", ["text"] = "30 Meter Reichweite\nSofort 6 sek. Abklingzeit\nTrifft einen Feind mit einem Blitzschlag, der auf einen in der Nähe befindlichen Feind überspringt. Der Zauber wirkt sich auf bis zu 3 Ziele aus und fügt jedem folgenden Ziel immer größeren Naturschaden zu." }
