entries[84832] = { ["name"] = "Zerlegen", ["text"] = "Nahkampfreichweite\nSofort\nEntwaffnet den Feind, entfernt alle Waffen, Schilde und andere getragene Ausrüstung. Hält 6 Sek. lang an." }
entries[84833] = { ["name"] = "Schießen", ["text"] = "5 - 30 Meter Reichweite\nSofort\nBenötigt Distanzwaffe\nSchießt auf einen Gegner und verursacht körperlichen Schaden." }
