entries[84836] = { ["name"] = "Mehrfachschuss", ["text"] = "5 - 30 Meter Reichweite\nSofort\nBenötigt Distanzwaffe\nFeuert eine Geschosssalve auf einen Feind sowie seine nahen Verbündeten, die 100% Waffenschaden verursacht. Trifft bis zu 3 Ziele." }
